          if ((d.scanned || 0) < 50) break;            // no quedan más pendientes
          if ((d.looked || 0) === 0) { if (++stall >= 2) { if (out) out.textContent += ' — frenado (lookups fallando, revisá API key/saldo).'; break; } }
          else stall = 0;
